#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-12

# page-serve serve.sh must not hand its caller's file descriptors to the daemon.
#
# serve.sh backgrounds a static http server that outlives the call. If that
# server inherits an fd the caller held open (a flock slot, a lock file, a pipe),
# the resource stays taken after the caller's job ends. Seen once: a server
# started inside a load-gated job kept the gate's slot lock fd open, so the slot
# stayed taken after the job finished.
#
# Behavioural: the parent opens a lock file on fd 9 and a second file on fd 7,
# runs the real serve.sh (stub portless and curl, no network), then inspects the
# server process. It must hold neither file. A server that cannot be inspected
# is a failure, never a pass.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SERVE="$REPO_ROOT/src/skills/page-serve/scripts/serve.sh"

PASS=0
FAIL=0
ok() { echo "  ✓ $1"; PASS=$((PASS + 1)); }
bad() { echo "  ✗ $1"; FAIL=$((FAIL + 1)); }

if [[ ! -f "$SERVE" ]]; then
    echo "FAIL: $SERVE not found" >&2
    exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork.pageserve.fds.XXXXXX")"
SERVER_PID=""
cleanup() {
    if [[ -n "$SERVER_PID" ]]; then
        # silent: post-cleanup (the server this test started may already be gone)
        kill "$SERVER_PID" 2>/dev/null || true
    fi
    rm -rf "$TMP"
}
trap cleanup EXIT

mkdir -p "$TMP/bin" "$TMP/root" "$TMP/proj"
echo '<p>x</p>' > "$TMP/root/index.html"

# Stubs: the portless 443 service and the proxy URL are not available here.
cat > "$TMP/bin/portless" <<'EOF'
#!/bin/bash
case "$1" in
  service) echo "Proxy on 443: responding" ;;
  alias) exit 0 ;;
esac
EOF
cat > "$TMP/bin/curl" <<'EOF'
#!/bin/bash
printf '200'
EOF
chmod +x "$TMP/bin/portless" "$TMP/bin/curl"

export PATH="$TMP/bin:$PATH"
export CLAUDE_PROJECT_DIR="$TMP/proj"

# Open files of one process, one path per line. Returns 1 when the process
# cannot be inspected (no /proc and no lsof).
open_files() {
    local pid="$1" fd target
    if [[ -d "/proc/$pid/fd" ]]; then
        for fd in /proc/"$pid"/fd/*; do
            # silent: gating-relaxed (an fd can close between the glob and the readlink; the list is only searched for two paths)
            if target="$(readlink "$fd")"; then printf '%s\n' "$target"; fi
        done
        return 0
    fi
    # silent: gating-relaxed (probe for the lsof binary; absence is reported by the return code)
    if ! command -v lsof >/dev/null 2>&1; then return 1; fi
    local out="" rc=0
    # silent: gating-relaxed (lsof exits 1 when it lists nothing; the caller checks for an empty list)
    out="$(lsof -p "$pid" -Fn 2>/dev/null)" || rc=$?
    printf '%s\n' "$out" | sed -n 's/^n//p'
}

LOCK9="$TMP/slot9.lock"
LOCK7="$TMP/slot7.lock"
: > "$LOCK9"
: > "$LOCK7"

echo "Behavioural: the daemon must not hold the caller's fds"
RC=0
OUT="$(
    exec 9>"$LOCK9" 7>"$LOCK7"
    bash "$SERVE" "$TMP/root" --name ork-ps-fds-test --no-screenshot 2>&1
)" || RC=$?

if [[ "$RC" -eq 0 && "$OUT" == *"url=https://ork-ps-fds-test.localhost/"* ]]; then
    ok "serve.sh served the page (rc 0)"
else
    bad "serve.sh did not serve (rc $RC): ${OUT:0:200}"
fi

STATE="$TMP/proj/.claude/state/page-serve/ork-ps-fds-test.json"
if [[ -f "$STATE" ]]; then
    SERVER_PID="$(sed -n 's/.*"pid": *\([0-9][0-9]*\).*/\1/p' "$STATE" | head -1)"
fi

ALIVE=0
if [[ -n "$SERVER_PID" ]]; then
    # silent: gating-relaxed (kill -0 is a liveness probe; a dead pid is reported as a failure below)
    if kill -0 "$SERVER_PID" 2>/dev/null; then ALIVE=1; fi
fi

if [[ -z "$SERVER_PID" ]]; then
    bad "no server pid in the state file, cannot inspect the daemon"
elif [[ "$ALIVE" -ne 1 ]]; then
    bad "server pid $SERVER_PID is not alive, cannot inspect the daemon"
else
    HELD=""
    OPEN_RC=0
    HELD="$(open_files "$SERVER_PID")" || OPEN_RC=$?
    if [[ "$OPEN_RC" -eq 0 && -n "$HELD" ]]; then
        ok "inspected the daemon (pid $SERVER_PID)"
        # String match, not `printf | grep -q`: grep -q under pipefail SIGPIPEs the producer (#603).
        if [[ "$HELD" == *"$LOCK9"* ]]; then bad "daemon holds the caller's fd 9 lock file"; else ok "daemon does not hold the fd 9 lock file"; fi
        if [[ "$HELD" == *"$LOCK7"* ]]; then bad "daemon holds the caller's fd 7 lock file"; else ok "daemon does not hold the fd 7 lock file"; fi
    else
        bad "could not list the daemon's open files (no /proc, no lsof, or empty list)"
    fi
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
